SELECT DECODE(KODE_BA,'2122','2131',KODE_BA) ba, ROUND(SUM(RP_ACTUAL)/1000) ytd, ROUND(SUM(IFF(DATE_TRUNC('month',BULAN)::DATE='2026-09-01',RP_ACTUAL,0))/1000) mtd FROM PRD_DB_PRESENTATION.PRS_COST.ESTATE_COST WHERE KODE_BA IN ('2121','2124','2131','2122') AND NOT (DECODE(KODE_BA,'2122','2131',KODE_BA)='2131' AND KODE_AFD='B') AND LEVEL_1='LANGSIR' AND BULAN>='2026-01-01' AND BULAN<'2026-10-01' GROUP BY 1 ORDER BY 1